import{_ as e,o,c as a,a2 as n}from"./chunks/framework.DNL3hc5c.js";const m=JSON.parse('{"title":"🥊 Tempo vs. The Competition","description":"","frontmatter":{},"headers":[],"relativePath":"doc/7-ecosystem/comparison.md","filePath":"doc/7-ecosystem/comparison.md"}'),i={name:"doc/7-ecosystem/comparison.md"};function r(s,t,l,d,c,g){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="🥊-tempo-vs-the-competition" tabindex="-1">🥊 Tempo vs. The Competition <a class="header-anchor" href="#🥊-tempo-vs-the-competition" aria-label="Permalink to &quot;🥊 Tempo vs. The Competition&quot;">​</a></h1><p>If you are choosing a date library today, you are likely looking at <strong>Day.js</strong>, <strong>Luxon</strong>, or <strong>date-fns</strong>. While these are excellent tools, they were all built for the legacy <code>Date</code> era.</p><p><strong>Tempo</strong> is the first premium wrapper built specifically for the <strong>Temporal API</strong> (Stage 4), giving it unique advantages that legacy libraries simply cannot match.</p><hr><h2 id="at-a-glance" tabindex="-1">At a Glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Tempo 💎</th><th style="text-align:left;">Raw Temporal API</th><th style="text-align:left;">Day.js / Moment</th><th style="text-align:left;">Luxon</th><th style="text-align:left;">date-fns</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Foundation</strong></td><td style="text-align:left;"><strong>Native Temporal</strong></td><td style="text-align:left;">Native Temporal</td><td style="text-align:left;">Legacy <code>Date</code></td><td style="text-align:left;">Legacy <code>Intl</code> + <code>Date</code></td><td style="text-align:left;">Legacy <code>Date</code></td></tr><tr><td style="text-align:left;"><strong>Precision</strong></td><td style="text-align:left;"><strong>Nanoseconds</strong></td><td style="text-align:left;">Nanoseconds</td><td style="text-align:left;">Milliseconds</td><td style="text-align:left;">Milliseconds</td><td style="text-align:left;">Milliseconds</td></tr><tr><td style="text-align:left;"><strong>Parsing</strong></td><td style="text-align:left;"><strong>Human-Centric</strong></td><td style="text-align:left;">Strict ISO Only</td><td style="text-align:left;">Strict / Plugin</td><td style="text-align:left;">Strict</td><td style="text-align:left;">Modular / Strict</td></tr><tr><td style="text-align:left;"><strong>Formatting</strong></td><td style="text-align:left;"><strong>Smart Tokens &amp; Getters</strong></td><td style="text-align:left;">Verbose <code>Intl</code> Only</td><td style="text-align:left;">Token-Based (Moment style)</td><td style="text-align:left;">Token-Based (Unicode)</td><td style="text-align:left;">Token-Based (Unicode helper)</td></tr><tr><td style="text-align:left;"><strong>Business Logic</strong></td><td style="text-align:left;"><strong>Terms System</strong></td><td style="text-align:left;">Manual Math</td><td style="text-align:left;">Manual Math</td><td style="text-align:left;">Manual Math</td><td style="text-align:left;">Manual Math</td></tr><tr><td style="text-align:left;"><strong>Time Zones</strong></td><td style="text-align:left;"><strong>First-Class</strong></td><td style="text-align:left;">First-Class</td><td style="text-align:left;">Plugin-based</td><td style="text-align:left;">Built-in</td><td style="text-align:left;">Separate Lib</td></tr><tr><td style="text-align:left;"><strong>Future-Proof</strong></td><td style="text-align:left;"><strong>100% (Native)</strong></td><td style="text-align:left;">100% (Native)</td><td style="text-align:left;">Maintenance Mode</td><td style="text-align:left;">Planned Sunset</td><td style="text-align:left;">Transitioning</td></tr></tbody></table><hr><h2 id="💎-why-tempo-wins" tabindex="-1">💎 Why Tempo Wins <a class="header-anchor" href="#💎-why-tempo-wins" aria-label="Permalink to &quot;💎 Why Tempo Wins&quot;">​</a></h2><h3 id="_1-the-terms-engine-business-intelligence" tabindex="-1">1. The &quot;Terms&quot; Engine (Business Intelligence) <a class="header-anchor" href="#_1-the-terms-engine-business-intelligence" aria-label="Permalink to &quot;1. The &quot;Terms&quot; Engine (Business Intelligence)&quot;">​</a></h3><p>Most libraries stop at &quot;adding 2 days.&quot; Tempo introduces the <strong>Terms</strong> system, allowing you to encode domain-specific logic (Fiscal Quarters, Meteorological Seasons, Academic terms, Zodiac Signs) directly into the Tempo <code>term</code> object.</p><blockquote><p><em>Competition:</em> You have to write custom utility functions and import them everywhere.</p></blockquote><h3 id="_2-human-centric-parsing" tabindex="-1">2. Human-Centric Parsing <a class="header-anchor" href="#_2-human-centric-parsing" aria-label="Permalink to &quot;2. Human-Centric Parsing&quot;">​</a></h3><p>Day.js and Luxon are quite strict. If your string isn&#39;t in exactly the right format, they fail. Tempo’s <strong>Snippet &amp; Layout</strong> engine is designed to be forgiving, extensible, and human-centric, handling relative dates like <code>&quot;next Friday&quot;</code> or <code>&quot;Christmas&quot;</code> out of the box.</p><blockquote><p><em>Competition:</em> Often requires an external library like <code>Chrono</code> or complex regex boilerplate.</p></blockquote><h3 id="_3-nanosecond-precision" tabindex="-1">3. Nanosecond Precision <a class="header-anchor" href="#_3-nanosecond-precision" aria-label="Permalink to &quot;3. Nanosecond Precision&quot;">​</a></h3><p>Native <code>Date</code> (and thus Day.js/Luxon/date-fns) is limited to milliseconds. For high-frequency trading, scientific data, or distributed systems, this isn&#39;t enough. Tempo inherits <strong>nanosecond precision</strong> from the Temporal API.</p><blockquote><p><em>Competition:</em> Capped at 1/1000th of a second.</p></blockquote><h3 id="_4-zero-leaky-abstractions" tabindex="-1">4. Zero &quot;Leaky Abstractions&quot; <a class="header-anchor" href="#_4-zero-leaky-abstractions" aria-label="Permalink to &quot;4. Zero &quot;Leaky Abstractions&quot;&quot;">​</a></h3><p>When you use a legacy library, you are often fighting the weirdness of the 1995 <code>Date</code> object (like months being 0-indexed). Tempo is built on <code>Temporal</code>, which was designed from the ground up to be mathematically sound and developer-friendly.</p><h3 id="_5-intelligent-formatting-shorthands" tabindex="-1">5. Intelligent Formatting &amp; Shorthands <a class="header-anchor" href="#_5-intelligent-formatting-shorthands" aria-label="Permalink to &quot;5. Intelligent Formatting &amp; Shorthands&quot;">​</a></h3><p>While native Temporal is highly precise, formatting dates for a UI in native Temporal is extremely verbose. It relies entirely on the native <code>Intl</code> API, requiring you to construct complex option objects or use long <code>.toLocaleString()</code> boilerplate just to output simple strings.</p><p>Tempo solves this by offering a <strong>Smart Token Engine</strong> (using <code>{yyyy}-{mm}-{dd}</code> placeholders) alongside built-in, highly optimized format getters like <code>.fmt.date</code>, <code>.fmt.time</code>, or <code>.fmt.dateTime</code>. In addition, Tempo automatically memoizes internal formatters under the hood, delivering top-tier performance without developer boilerplate.</p><blockquote><p><em>Competition:</em> Raw Temporal requires verbose <code>Intl</code> configurations; legacy libraries require large plugins or separate helper imports.</p></blockquote><hr><h2 id="the-temporal-transition-strategy" tabindex="-1">The Temporal Transition Strategy <a class="header-anchor" href="#the-temporal-transition-strategy" aria-label="Permalink to &quot;The Temporal Transition Strategy&quot;">​</a></h2><p>As JavaScript transitions natively to the Temporal API, the existing ecosystem is taking different paths. This presents a unique opportunity for new, Temporal-first architectures like Tempo:</p><ul><li><strong>Luxon:</strong> The creators have explicitly stated they <a href="https://github.com/moment/luxon/discussions/970" target="_blank" rel="noreferrer">plan to sunset Luxon</a> as Temporal adoption grows, eventually becoming &quot;a distant memory.&quot;</li><li><strong>Day.js:</strong> Architecturally bound to the legacy <code>Date</code> object to <a href="https://github.com/iamkun/dayjs" target="_blank" rel="noreferrer">maintain its &lt;2kB size</a> and Moment.js compatibility. It cannot evolve to support native Temporal objects and will remain a tool for legacy codebases.</li><li><strong>date-fns:</strong> Transforming into a companion utility kit tailored around native Temporal objects (evidenced by their bridging project, <a href="https://github.com/date-fns/interim" target="_blank" rel="noreferrer"><code>date-fns/interim</code></a>), while maintaining dual support for legacy <code>Date</code>.</li></ul><p>Because Luxon is bowing out and Day.js cannot evolve architecturally without losing its identity, <strong>Tempo</strong> steps in as the premier, dedicated premium wrapper built <em>specifically</em> for the Temporal era from day one.</p><hr><h2 id="which-should-you-choose" tabindex="-1">Which should you choose? <a class="header-anchor" href="#which-should-you-choose" aria-label="Permalink to &quot;Which should you choose?&quot;">​</a></h2><ul><li><strong>Choose Day.js if:</strong> You have a legacy codebase and need a tiny &lt;2KB patch for simple tasks, and are comfortable using a library in maintenance mode.</li><li><strong>Choose Luxon if:</strong> You need a stable bridge for environments that don&#39;t yet support Temporal, but keep in mind it is actively planning for sunset.</li><li><strong>Choose date-fns if:</strong> You have an existing codebase heavily invested in date-fns pipelines and want to leverage their transitional bridge as you migrate.</li><li><strong>Choose <a href="https://magmacomputing.github.io/magma/functions/" target="_blank" rel="noreferrer">@magmacomputing/tempo-fns</a> if:</strong> You prefer pure, tree-shakeable functional utilities designed natively for Temporal objects (and Tempo terms) without the overhead of a class-based wrapper.</li><li><strong>Choose Tempo if:</strong> You want a premium, Temporal-first architecture that provides <strong>fluent chaining</strong>, <strong>high precision</strong>, <strong>human-centric parsing</strong>, and the ability to model <strong>complex business-date logic</strong> directly into your application.</li></ul><p><a href="./../../README.html#⚡-quick-start"><strong>Ready to start? See the Quick Start Guide →</strong></a></p>',32)])])}const u=e(i,[["render",r]]);export{m as __pageData,u as default};
